{"implementation":"def solve(case):
    segments = case['segments']
    budget = case['budget']
    total_min = sum(s['minimum'] for s in segments)
    total_cap = sum(s['capacity'] for s in segments)
    if budget < total_min or budget > total_cap:
        return {'error': 'budget out of range'}
    alloc = {s['name']: s['minimum'] for s in segments}
    remaining = budget - total_min
    seg_data = [(s['name'], s['importance'], s['capacity'], i) for i, s in enumerate(segments)]
    while remaining > 0:
        best = None
        best_ratio = -1.0
        best_idx = -1
        for name, imp, cap, idx in seg_data:
            if alloc[name] < cap:
                ratio = imp / (alloc[name] + 1)
                if ratio > best_ratio or (ratio == best_ratio and idx < best_idx):
                    best_ratio = ratio
                    best_idx = idx
                    best = name
        if best is None:
            break
        alloc[best] += 1
        remaining -= 1
    return {
        'allocations': alloc,
        'names': [s['name'] for s in segments],
        'budget': budget
    }"}
